import wandb
api = wandb.Api()
for rid in ['li451oi4', 'z9nqlucg']:
    run = api.run(f'xiaoyucorynne-/recovery_aware_struct_prune/{rid}')
    print(f'=== {run.name} (state={run.state}) ===')
    hist = run.history(samples=500, pandas=False)
    for row in hist:
        step = row.get('_step', '?')
        keys_of_interest = [k for k in row.keys() if any(x in k.lower() for x in ['reward','loss','grad','entropy','kl','frac','zero_std'])]
        if keys_of_interest:
            vals = {k: row[k] for k in sorted(keys_of_interest) if row[k] is not None}
            if vals:
                print(f'  step {step}: {vals}')
" 2>&1

